export const denialCategories: DenialCategory[] = [
  "Eligibility", "Authorization", "Coding", "Bundling",
  "Contractual", "Coverage", "Timely filing", "Patient responsibility", "Data quality",
  "Provider eligibility", "Documentation", "Liability and workers comp",
];

export const getDenialCode = (code: string) =>
  denialCodes.find((d) => d.code.toLowerCase() === code.toLowerCase());
